import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { ListToolsRequestSchema, CallToolRequestSchema } from '@modelcontextprotocol/sdk/types.js';

// --- gateway side: low-level Server, JSON Schema straight from the OpenAPI doc ---
const server = new Server(
  { name: 'mcprouter', version: '0.1.0' },
  { capabilities: { tools: {} } }          // REQUIRED, else setRequestHandler throws
);
server.setRequestHandler(ListToolsRequestSchema, () => ({
  tools: [{ name: 'list_orders', description: '…', inputSchema: openapiJsonSchema }]
}));
server.setRequestHandler(CallToolRequestSchema, async (req, extra) => {
  // req.params.arguments is the RAW client object — no validation, no coercion.
  // extra.authInfo is whatever the transport attached (see gotchas).
  return { content: [{ type: 'text', text: '…' }] };
});

// --- test seam: no process, no port ---
const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
const client = new Client({ name: 'test', version: '0.0.0' });
await Promise.all([server.connect(serverTransport), client.connect(clientTransport)]);

await client.listTools();                                   // → { tools: [...] }
await client.callTool({ name: 'list_orders', arguments: {} }); // → { content: [...] }

await clientTransport.close();  // closes BOTH sides, fires onclose on both
